import{_ as s,C as l,o as i,c as r,j as t,a as e,E as d,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"体用生克篇之四：十应","description":"统合体用、衰旺、动静与向背，建立多维判断的基本秩序。","frontmatter":{"title":"体用生克篇之四：十应","description":"统合体用、衰旺、动静与向背，建立多维判断的基本秩序。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/ten-responses.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/ten-responses.md","lastUpdated":1787730063000}'),p={name:"yijing/meihua-yishu/ti-yong-sheng-ke/ten-responses.md"};function h(c,a,g,b,u,m){const n=l("DaoTextReading");return i(),r("div",null,[a[0]||(a[0]=t("h1",{id:"【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占",tabindex:"-1"},[e("【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占 "),t("a",{class:"header-anchor",href:"#【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占","aria-label":'Permalink to "【体用生克篇之四】十应奥论·体用论·衰旺·动静·向背·静占"'},"​")],-1)),a[1]||(a[1]=t("blockquote",null,[t("p",null,"本篇是全书理论体系的收官。前几篇分别讲了体用、十八占、三要，这篇把三者融为一体，说清楚它们之间的关系，并补充了衰旺、内外、动静、向背、静占五个重要概念。")],-1)),a[2]||(a[2]=t("hr",null,null,-1)),a[3]||(a[3]=t("h2",{id:"📜-原文",tabindex:"-1"},[e("📜 原文 "),t("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),d(n,{colophon:"十应奥论 · 遗论 · 静占",tone:"ink",sections:[{id:"sec-01",label:"十应奥论",showLabel:!0,sentences:[["十应固出于三要，而妙乎三要。"],["但以耳目所得，如见吉兆而终须吉，若逢",{text:"凶谶",glossary:"g01"},"不免乎凶，理之自然也。"],["然以此而遇吉凶，亦有未然者也。"],["黄金白银，为世之宝，三要得之，必以为祥。"],["十应之决，遇金有不吉者，利刃锐兵，世谓凶器，三要得之，亦以为凶；十应之说，遇兵刃反有吉者。"],["又若占产见少男，三要得之为生子之喜，十应见少男则凶。"],["占病遇棺，三要占之必死；十应以为有生意。"],["例多若此，是占卜物者，不可无应也。"]]},{id:"sec-02",label:"十应目论",showLabel:!0,sentences:[["十应并以体卦为主，诸用卦为用。"],["每以内分外体，用卦参观为妙。"],["内卦不吉而外卦又吉，可以解其不吉；内卦吉而外卦不吉，反破其吉。"],["若内外卦全吉，则断然吉。"],["全凶则断然凶。"],["其内吉外凶，内凶外吉，又须详理以断吉凶，慎不可",{text:"胶柱鼓瑟",glossary:"g02"},"也。"],["外卦十应之目，则有天时、地理及写字等，其十一类之应，并以体卦为主，而随其所应以为用也。"]]},{id:"sec-03",label:"复明天时之应",showLabel:!0,sentences:[["如天无",{text:"云翳",glossary:"g03"},"，明朗之际，为干之时。"],["干、兑为体，则比和而吉；坎为体，则逢生而大吉。"],["坤、艮为体，则泄气。"],["震、巽为体，则见克而不吉矣。"],[{text:"晴霁",glossary:"g04"},"日中，为离之时，坤、兑为体则吉。"],["雨雪为坎之时，震、巽为体则吉，离为体则不吉。"],["雷风为震、巽之时，离为体则吉，坤、艮为体则不吉。"],["此天时之应也。"]]},{id:"sec-04",label:"复明地理之应",showLabel:!0,sentences:[["茂树秀竹，为震之地。"],["离与震、巽为体则吉，坤、艮为体则凶。"],["江湖、河池、川泽、溪涧为坎之地，震、巽与坎为体则吉，而离为体则不吉。"],["窑灶之地为离，坤、艮并离为体则吉，而干、兑为体则不吉。"],["岩穴之地为艮、干、兑与艮为体则吉，坎为体则不吉。"],["此地理之应也。"]]},{id:"sec-05",label:"复明人事之应",showLabel:!0,sentences:[["人事有论卦象五行者，有不论卦象五行者。"],["论卦象，则老人属干，老妇属坤，艮为少男，兑为少女之类。"],["五行生克，比和之理，与前天时、地理之卦同断。"],["其不分卦象五行者，则以人事之纷，了见杂出，有吉有凶，此应则随其吉凶而为之兆也。"],["又观其事则亦为某人。"],["此人事之应也。"]]},{id:"sec-06",label:"复明时令之应",showLabel:!0,sentences:[["时令不必论卦象，但详其令，月日值之五行衰旺之气。"],["旺者，如寅卯之月日则木旺，巳午之月日火旺，申酉之月日金旺，亥子之月日水旺，辰戌丑未之月日土旺。"],["衰者，如木旺则土衰，土旺则水衰，水旺火衰，火旺则金衰，金旺则木衰。"],["是故生体卦气，宜值时之旺气，不宜衰气。"],["如克体卦气，则宜乘衰。"],["此时令之应也。"]]},{id:"sec-07",label:"复明方卦之应",showLabel:!0,sentences:[["即分方之卦。"],["如离南、坎北、震东、兑西、巽东南、干西北、艮东北、坤西南类也。"],["论吉凶者，看来占之人在何卦位，而以用卦参详。"],["如坎为用卦，宜在坎与震、巽之位，在离则不吉。"],["离为用卦，宜在离与坤、艮之位，在干、兑二位则不吉矣。"],["盖宜在本卦之方，为用卦生之方，不宜受用卦克也。"],["若夫气在之卦所在之方，又当审之。"],["如水从坎来，为坎卦气旺。"],["水从坤、艮来，则坎之卦气衰。"],["火从南来，为离卦气旺，如从北来，则离之卦气衰。"],["余皆仿此。"],["大抵本卦之方，生为旺，受克为衰。"],["宜以体卦参之。"],["生体卦气，宜受旺方；克体卦气，宜受克方。"],["此方卦之应也。"],["又震、巽之方，不论坤、艮。"],["坤、艮之方不论坎。"],["坎方不论离。"],["离方不论干。"],["干、兑之方，不论震、巽。"],["以其寓卦受方卦之克也。"]]},{id:"sec-08",label:"复明动物之应",showLabel:!0,sentences:[["动物有论卦象者。"],["干为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊，又螺蚌龟鳖为离之象，鱼类为坎之属，此动物之卦，以体详与。"],["又不论卦象五行者，如乌鸦报灾，灵鹊报喜，渔雁主有书信，蛇虫防有毒害，鸡唱为家音，马嘶为动意。"],["此动物之应也。"]]},{id:"sec-09",label:"复明静物之应",showLabel:!0,sentences:[["器物之类，有论卦象者。"],["如水属坎，火属离，水之气属震、巽，金之气属干、兑，土之气属坤、艮，为体卦，要参详。"],["其不分卦象者，但观其器物之兆，如物之圆者，事成；器之缺者，事败。"],["又详其器物是何物，如笔砚主文书之事，",{text:"袍笏",glossary:"g08"},"主官职之事，",{text:"樽俎",glossary:"g09"},"之具有宴集，枷锁之具防官灾。"],["百端不一，审其物器。"],["此静物之应也。"]]},{id:"sec-10",label:"复明言语之应",showLabel:!0,sentences:[["闻人言语，不论卦象，但详其所言之事绪而占卜之。"],["应闻吉语则吉，闻凶语则凶，若闻闹丛言语喧集，难以决断。"],["若定人少之处，或言语可辨其事绪，则审其所言何事，心领而意会之。"],["如说朝廷迁选，可以求名；论江湖州郡，主出行；言争讼之事，主官司；言喜庆之事，利婚姻。"],["事绪不一，随所闻以依之。"],["此言语之应也。"]]},{id:"sec-11",label:"复明声音之应",showLabel:!0,sentences:[["耳所闻之声音而论卦象，则雷为震，风声为巽，雨声为坎，水声为坎，鼓拍槌拆之声出于木者，皆属震、巽，钟声、",{text:"铃铙",glossary:"g05"},"之声出于金者，皆属干、兑。"],["此声音之论卦象。"],["若为体，参详决之，如闻声音有欢笑之声，主有喜；悲愁之声，主有忧；歌唱之声，主快乐；怒号之声，主争喧。"],["至若物声，则鸦声报灾，鹊声传喜，鸿雁声主远信，",{text:"鸡凫",glossary:"g13"},"之声为佳音。"],["此类推声音之应也。"]]},{id:"sec-12",label:"复明五色之应",showLabel:!0,sentences:[["五色不论卦象，但以所见之色推五行。"],["青碧绿色属木，红紫赤色属火，白属金，黑属水，黄属土。"],["外应之五行，详于内卦。"],["体用生克、比和，吉凶可见。"],["此五色之应也。"]]},{id:"sec-13",label:"复明写字之应",showLabel:!0,sentences:[["淡中浓墨名为",{text:"淬",glossary:"g06"},"，浓墨中间薄似云，点画误书名",{text:"鬼笔",glossary:"g07"},"，定知贼在暗中缠。"],["涕为流泪防丧服，定主忧惊梦里眠。"],[{text:"鬼笔",glossary:"g07"},"误书防窃盗，定知方位与通传。"],["此写字之应验也。"]]},{id:"sec-14",label:"遗论",showLabel:!0,sentences:[["万物卦数，本由于《易》。"],["今观此书，止用五行生克之理。"],["十应三要之诀，例不同《易》，何也？"],["盖未有《易》书，先有《易》理。"],["《易》书作于",{text:"四圣",glossary:"g12"},"之后，《易》理着于",{text:"四圣",glossary:"g12"},"之先。"],["人心皆有《易》理，则于《易》也，占卜无所用卦，卦即《易》也。"],["若得《易》卦爻，观其爻辞，以断吉凶悔吝，更为妙也，未尝不用《易》。"],["又观寓物卦数，起例之篇，止用内卦，不用外卦，何也？"],["盖泛泛起卦之诀，十应为传授之诀。"],["若观梅例曰「今日观梅得革，知女折花，有伤股」，明日观梅得革，亦谓女子折花，可乎？"],["占牡丹例曰：「今日算牡丹为马践毁」，异日算牡丹亦为马所践，可乎？"],["是必明其理。"],["又于地风升卦，无饮食之兆而知有人相请。"],["此要外应诀之。"]]},{id:"sec-15",label:"体用",showLabel:!0,sentences:[["凡占卜成卦，即画成三重：本卦、互卦、变卦也。"],["使于本卦分体用，此一体一用也。"],["以卦五行明生克比和之理，此一用卦。"],["最切看互卦变卦，互变亦用也。"],["此内之体用也。"],["又次看应卦，亦用也。"],["此合内外之体用也。"],["然则不止一体一用，所谓",{text:"体一用百",glossary:"g15"},"也。"],["生克即分体用，则论生克。"],["生体则吉，克体则凶，比和则吉，不必论矣。"],["生体多者则愈吉，克体多者则愈凶。"],["然此卦生体，诸卦有克此卦者，彼灭其吉。"],["此卦克体，诸卦又有克此卦者，稍解其穷。"],["有生此卦者吉，有克此卦者凶。"],["此体用之生克，然卦之生克，有不论体用者。"],["如占天时，有震则有雷，有巽则有风，逢坎则有雨，逢离则晴。"],["此一定之理。"],["又有不然者，如论卦中干、兑多，则震无雷，巽亦无风，又必有此诀也，皆隐然外卦之意。"],["如观梅有女折花，算牡丹有马践，地风升有饮食兆。"],["此又非外应之兆不能决也。"]]},{id:"sec-16",label:"体用论",showLabel:!0,sentences:[["心易寓物之用，以体为主。"],["然人如一体一用之常，不知一体百用之变。"],["并体之变，全卦为内，卦内亦不知一用，而互变皆用也。"],["三要十应之卦，外卦也，外亦不一，无非用也。"],["学寓物者，得体用以为至术，十应则罕有之，后则三要以为全术。"],["且谓体用自体用，三要自三要，遂以体用决吉凶，以三要为吉凶之兆。"],["孰知三要、十应、体用之致？"],["呜乎！"],["体用不可无三要，十应不可无体用。"],["体用、三要、十应，",{text:"理无间然",glossary:"g14"},"也。"],["如此者，是谓心易之全术，而可以尽占卜之道也。"],["又如干、兑多则巽无风；坤、艮多则坎无雨；坎多，则离亦不晴。"],["盖以干、兑之金，克震、巽之木；坤、艮之土，克坎水；坎水克离火也。"],["此又须通变而推验之。"],["又若占饮食，有坎则有酒，有兑则有食。"],["如遇坤、艮，则坎亦无酒，离值则兑亦无食。"],["余皆可以类推。"],["故举此二类，为心易生克之例耳。"]]},{id:"sec-17",label:"衰旺论",showLabel:!0,sentences:[["既明生克，当看衰旺。"],["旺者，如春震、巽木，夏离火，秋干、兑金，冬坎水，四季之月坤、艮土是也。"],["衰者，如春坤、艮，夏干、兑，秋震、巽，冬离，四季之月坎是也。"],["凡占卜，体卦宜盛旺。"],["气旺而又逢生则吉，重遇克则凶。"],["若体衰而逢克，则其凶甚矣。"],["体衰而有生体之卦，则衰稍解。"],["大抵体之卦宜旺，生体之卦气亦宜旺，克体之卦气宜衰。"],["此心易论衰旺之诀也。"]]},{id:"sec-18",label:"内外论",showLabel:!0,sentences:[["凡占卜，体用为内，诸应卦为外卦，此占卜之例也。"],["诸应卦与三要之应，与十应之应，必合内外卦而断之也。"],["苟不知合内外卦为断，谓体用自体用，三要十应自三要十应，如此则鲜见其有验者。"],["然十应罕有知者，如前「奥论」云：金银为世宝，三要为吉者，若震、巽为体，则金克木，反为不吉。"],["兵刃为世凶，三要为凶者，若坎为体，则金生水，反为不凶。"],["占产见男子，谓有生子兆，设坎为体，少男为艮土，土克水，产反不吉。"],["占疾见棺必死，若遇离体，则木生火而反吉。"],["似此之类，则内卦不可无外卦，外卦不可无内卦。"],["占卜之精者，无非合内外之道也。"]]},{id:"sec-19",label:"动静",showLabel:!0,sentences:[["凡占决，虽明动静之机，然有理之常，有事之变。"],["阳动而阴静，一动一静者，理之常；此静而彼动，一静百动者，事之变也。"],["天下之事物，纷纷群动。"],["我则以一静而待之。"],["事物之动，各有其端，我则以一静而测之。"],["不动不占，不因事不占。"],["占卜之际，察其群物之事，物动而凶者，兆吾卦之凶；物动而吉者，兆吾卦之吉。"],["然于闹喧市缠之地，人物杂扰，群物满前，何事拓何物为吉？"],["吾占卜之应，此又推乎理而合其事。"],["盖于群动之中，或观其身临吾耳目之近者，可以先见者，或以群事分明者，或吾之一念所在者，此发占之所用。"],["若求名，则于群动之中，或于官府，或有文书及",{text:"袍笏",glossary:"g08"},"仪卫之物，则为得官之应。"],["若占讼事，而忽逢",{text:"笞杖枷锁",glossary:"g11"},"之具，则讼终不吉。"],["占病而不见",{text:"衰麻棺椁",glossary:"g10"},"之物者，病当无恙。"],["凡此，所谓事事相关，物物相应，是以验吾占卦之切要也。"],["至若坐则应迟，行则应速，走则愈速，卧则愈迟，此则察其动之端也。"],["吾心本静，人来占卜，起念以应之，即动也。"],["以此动而测彼动，于此之念而求彼之验，诚而神知之。"],["知此者，可以知动静之机矣。"]]},{id:"sec-20",label:"向背",showLabel:!0,sentences:[["凡占卜求应，必须审其向背。"],["向者，为事物之应，相向而来。"],["背者，谓事物之应，相背而去也。"],["如鸦报灾，鸦飞适来，其灾将至；鸦飞而去，则灾已过去也。"],["如鹊报喜，鹊飞适来，其喜将至；鹊飞已去，则喜已过去也。"],["至于外应之卦皆然。"],["其克体之卦，器物方来，其祸将至，去则祸散。"],["其生体之卦，器物方来则吉，去则吉已过矣。"],["其它应兆皆然。"],["此为占卦向背至当理也。"]]},{id:"sec-21",label:"静占",showLabel:!0,sentences:[["凡占在静室，无所闻见，则无外卦，即不论外卦。"],["但以全卦年月日值五行衰旺之气，以体用决之。"]]}],glossary:[{id:"g01",term:"凶谶",pinyin:"xiōng chèn",meaning:"凶险的预兆"},{id:"g02",term:"胶柱鼓瑟",pinyin:"jiāo zhù gǔ sè",meaning:"固执不知变通，典出《史记》，胶住琴柱则音不可调"},{id:"g03",term:"云翳",pinyin:"yún yì",meaning:"云层遮蔽，翳：遮蔽"},{id:"g04",term:"晴霁",pinyin:"qíng jì",meaning:"雨后天晴"},{id:"g05",term:"铃铙",pinyin:"líng náo",meaning:"铃与铙，金属打击乐器"},{id:"g06",term:"淬",pinyin:"cuì",meaning:"此处指墨色浓淡不均"},{id:"g07",term:"鬼笔",pinyin:"—",meaning:"书写时笔画有误，如鬼画符"},{id:"g08",term:"袍笏",pinyin:"páo hù",meaning:"官服与朝笏，代指官职"},{id:"g09",term:"樽俎",pinyin:"zūn zǔ",meaning:"酒器与食器，代指宴席"},{id:"g10",term:"衰麻棺椁",pinyin:"—",meaning:"丧服（衰麻）与棺材，代指丧事"},{id:"g11",term:"笞杖枷锁",pinyin:"chī zhàng jiā suǒ",meaning:"刑具，代指官讼刑罚"},{id:"g12",term:"四圣",pinyin:"—",meaning:"伏羲、文王、周公、孔子，《易》之四圣"},{id:"g13",term:"鸡凫",pinyin:"jī fú",meaning:"鸡与野鸭"},{id:"g14",term:"理无间然",pinyin:"—",meaning:"道理之间没有间隙，完全融通"},{id:"g15",term:"体一用百",pinyin:"—",meaning:"体只有一个，用却有百种"}],"aria-label":"十应原文"}),a[4]||(a[4]=o("",96))])}const x=s(p,[["render",h]]);export{y as __pageData,x as default};
